%% ── Colours ──────────────────────────────────────────────────────────────────
cRaw  = [0.89 0.10 0.11];   % red
cMAV  = [1.00 0.50 0.00];   % orange
cLP   = [0.65 0.47 0.11];   % brown
cComp = [0.30 0.69 0.29];   % green
cKF1  = [0.60 0.31 0.64];   % purple
cKF2  = [0.22 0.49 0.72];   % blue
cKF3  = [0.97 0.51 0.75];   % pink
cKF9  = [0.00 0.00 0.00];   % black (firmware)
