%% ── Per-filter figure data ───────────────────────────────────────────────────
filter_data   = {r_raw,   r_mav,                r_lp,                      r_comp, ...
                 r_kf1,   r_kf2,                r_kf3,                     r_kf9};
filter_names  = {'Raw ToF', 'Moving Avg (N=10)', 'Low-pass IIR (\alpha=0.85)', ...
                 'Complementary (\alpha=0.98)', '1D KF 1-state', ...
                 '1D KF 2-state (z, v_z)', '1D KF 3-state (z, v_z, a_z)', ...
                 'Kalman9D (firmware)'};
filter_colors = {cRaw, cMAV, cLP, cComp, cKF1, cKF2, cKF3, cKF9};
filter_lw     = [1.0   1.6   1.6    2.0   1.4   1.4   1.4   2.8];

offsets = [0 40 80 120 160 200 240 280];

%% ════════════════════════════════════════════════════════════════════════════
%% Fig 0 — Combined: all 8 filters on one axes
%% ════════════════════════════════════════════════════════════════════════════
figure('Name','A3 — All filters combined','Position',[60 60 900 680]);
ax0 = axes('Position',[0.13 0.13 0.82 0.74]);
hold on;

yline(ax0, TRUE_Z, '--', 'Color',cTrue, 'LineWidth',1.8, 'HandleVisibility','off');
for k = 1:7
    plot(ax0, T, filter_data{k}, '-', 'Color',filter_colors{k}, 'LineWidth',filter_lw(k));
end
plot(ax0, T, r_kf9, '-', 'Color',cKF9, 'LineWidth',2.8);

xline(ax0, 15, ':', 'Color',[0.65 0.65 0.65], 'LineWidth',1.2, 'HandleVisibility','off');
text(ax0, 0.3, 1.0255, 'True altitude = 1.0 m', 'FontSize',21, 'Color',cTrue);
text(ax0, 15.15, 0.9725, 'SS window \rightarrow', 'FontSize',18, ...
     'Color',[0.55 0.55 0.55], 'FontAngle','italic', 'Interpreter','tex');

set(ax0, 'XLim',[0 20], 'YLim',[0.97 1.03], 'Box','off', ...
         'YGrid','on', 'XGrid','off', 'GridAlpha',0.25, 'GridLineStyle','--');
xlabel(ax0, 'Time  (s)', 'FontSize',25);
ylabel(ax0, 'Estimated altitude  (m)', 'FontSize',25);
legend(ax0, filter_names, 'FontSize',16, 'Location','northeast', 'Box','off', 'Interpreter','tex');
hold off;

%% ════════════════════════════════════════════════════════════════════════════
%% Figs 1–8 — One figure per filter
%% ════════════════════════════════════════════════════════════════════════════
for k = 1:8
    figure('Name', ['A3 — ' filter_names{k}], ...
           'Position', [60+offsets(k)  60+offsets(k)  900  680]);
    ax = axes('Position',[0.13 0.13 0.82 0.74]);
    hold on;

    yline(ax, TRUE_Z, '--', 'Color',cTrue, 'LineWidth',1.8, 'HandleVisibility','off');
    plot(ax, T, filter_data{k}, '-', 'Color',filter_colors{k}, 'LineWidth',filter_lw(k));
    xline(ax, 15, ':', 'Color',[0.65 0.65 0.65], 'LineWidth',1.2, 'HandleVisibility','off');
    text(ax, 0.3, 1.0255, 'True altitude = 1.0 m', 'FontSize',21, 'Color',cTrue);

    set(ax, 'XLim',[0 20], 'YLim',[0.97 1.03], 'Box','off', ...
            'YGrid','on', 'XGrid','off', 'GridAlpha',0.25, 'GridLineStyle','--');
    xlabel(ax, 'Time  (s)', 'FontSize',25);
    ylabel(ax, 'Estimated altitude  (m)', 'FontSize',25);
    legend(ax, {filter_names{k}}, 'FontSize',21, 'Location','northeast', ...
           'Box','off', 'Interpreter','tex');
    hold off;
end

%% ════════════════════════════════════════════════════════════════════════════
%% Fig 9 — Absolute error (mm) from true altitude
%% ════════════════════════════════════════════════════════════════════════════
figure('Name','A3 — Absolute error (mm)','Position',[80 80 900 680]);
ax9 = axes('Position',[0.13 0.13 0.82 0.74]);
hold on;

for k = 1:8
    err_mm = abs(filter_data{k} - TRUE_Z) * 1000;
    plot(ax9, T, err_mm, '-', 'Color',filter_colors{k}, 'LineWidth',filter_lw(k));
end
xline(ax9, 15, ':', 'Color',[0.65 0.65 0.65], 'LineWidth',1.2, 'HandleVisibility','off');
text(ax9, 15.15, 19.5, 'SS window \rightarrow', 'FontSize',18, ...
     'Color',[0.55 0.55 0.55], 'FontAngle','italic', 'Interpreter','tex');

set(ax9, 'XLim',[0 20], 'YLim',[0 22], 'Box','off', ...
         'YGrid','on', 'XGrid','off', 'GridAlpha',0.25, 'GridLineStyle','--');
xlabel(ax9, 'Time  (s)', 'FontSize',25);
ylabel(ax9, '|Error|  (mm)', 'FontSize',25);
legend(ax9, filter_names, 'FontSize',16, 'Location','northeast', 'Box','off', 'Interpreter','tex');
hold off;

