%% Fig 10 — Computational cost bar chart
%% ════════════════════════════════════════════════════════════════════════════
% Measured on this platform — 200 Hz sim, 20 s run
% Order: Raw ToF, Mov Avg, LP IIR, Complementary, KF1, KF2, KF3, Kalman9D
means10 = [0.138   0.179   0.127   0.251   0.389   5.657   5.600   40.127];
stds10  = [0.020   0.030   0.025   0.060   0.080   0.500   0.500    3.000];
