ax10  = axes('Position',[0.12 0.22 0.84 0.65]);
hold on;

for i = 1:8
    bar(ax10, i, means10(i), 0.6, 'FaceColor',cols10{i}, 'EdgeColor','k', ...
        'LineWidth',0.5, 'FaceAlpha',0.72);
