     'FontSize',17, 'Color',[0.00 0.00 0.00], 'Interpreter','tex');

set(ax10, 'XTick',1:8, 'XTickLabel',xlabs10, 'XTickLabelRotation',22, ...
          'XLim',[0.3 8.7], 'YLim',[0 48], 'Box','off', ...
          'YGrid','on', 'XGrid','off', 'GridAlpha',0.25, 'GridLineStyle','--');
xlabel(ax10, 'Filter', 'FontSize',25);
